	private static OptimizerRuleDescriptor productionRule(int descriptorId, String stableId, String runtimeProofId,
			String before, String after, String proofId, String positiveTest, String negativeTest) {
		return new OptimizerRuleDescriptor(descriptorId, stableId, Kind.LOGICAL_EQUIVALENCE, Disposition.IMPLEMENTED,
				before, after, OptimizationGoal.BAG_SEMANTICS, Set.of("scope-local"),
				Set.of("SPARQL errors preserved", "graph scope preserved"), Set.of(proofId), runtimeProofId,
				"runtime proof bit plus result-bag contract", LOGICAL_RULE_PROGRAM,
				"PackedLogicalRuleProgram -> PackedMemo", List.of(positiveTest), List.of(negativeTest),
				"optimizer.rule.rejected." + stableId, "local proof regime; fixpoint certification required");
	}

	private static OptimizerRuleDescriptor researchRule(RewriteRuleCatalog.Entry entry) {
		Disposition disposition = switch (entry.status()) {
		case IMPLEMENTED, DELEGATED_EXISTING -> Disposition.IMPLEMENTED;
		case PARTIAL, METADATA_GATED -> Disposition.PARTIAL;
		case UNSUPPORTED -> Disposition.UNSUPPORTED;
		};
		return new OptimizerRuleDescriptor(2000 + entry.id(), "research-" + entry.name(),
				Kind.RESEARCH_PROPOSAL, disposition, entry.name(), entry.name(), OptimizationGoal.BAG_SEMANTICS,
				Set.of(), Set.of(), Set.of(), "", "reviewed SPARQL rewrite inventory", "",
				"research inventory", List.of(), List.of(), "optimizer.rule.rejected.research-" + entry.id(),
				"catalog classification only");
	}

	private static OptimizerRuleDescriptor optimization(int id, String stableId, Kind kind, Disposition disposition,
			String implementation, String contract) {
		return optimization(id, stableId, kind, disposition, implementation, contract, List.of(), List.of());
	}

	private static OptimizerRuleDescriptor optimization(int id, String stableId, Kind kind, Disposition disposition,
			String implementation, String contract, List<String> positiveTests, List<String> negativeTests) {
		return new OptimizerRuleDescriptor(id, stableId, kind, disposition, contract, contract,
				OptimizationGoal.BAG_SEMANTICS, Set.of(), Set.of(), Set.of(), "", "optimizer architecture contract",
				implementation, "closed-world optimizer registration", positiveTests, negativeTests,
				"optimizer.rule.rejected." + stableId, "declared implementation and budget regime");
	}

